import argparse
import base64
import io
import json
import os
import sys
import tarfile
from pathlib import Path
from typing import Optional, Tuple

import requests


DEFAULT_API_BASE = "https://repo.workpeg.com"
JWT_ENV = "WORKPEG_PK"
API_ENV = "WORKPEG_API_BASE"
PATH_ENV = "WORKPEG_SUBMIT_PATH"

# Files that must never leave the machine in a bundle/upload — env files, key
# material, and credential stores. Matched by basename (case-insensitively).
_SECRET_NAMES = frozenset({
    ".envrc", ".netrc", ".npmrc", ".pypirc", ".htpasswd", ".dockercfg",
    "credentials", "id_rsa", "id_dsa", "id_ecdsa", "id_ed25519",
})
_SECRET_SUFFIXES = (".pem", ".key", ".pfx", ".p12", ".keystore", ".jks")


#: Never bundled, at any depth. ``function submit`` also drops ``build`` and
#: ``dist`` at any depth; ``project submit`` drops those only at the roots of
#: ``ui/`` and ``function/`` and shares the rest of this list.
ALWAYS_EXCLUDED = frozenset({
    ".git",
    "__pycache__",
    ".pytest_cache",
    ".mypy_cache",
    ".venv",
    "venv",
    ".DS_Store",
    # credential stores — never ship these off the machine
    ".ssh",
    ".aws",
    ".gnupg",
})


def _looks_secret(name: str) -> bool:
    """A basename that looks like a secret (``.env``/``.env.local``, a key file,
    a credential store) — excluded from bundles and uploads."""
    lo = name.lower()
    return (
        lo == ".env"
        or lo.startswith(".env.")
        or lo in _SECRET_NAMES
        or lo.endswith(_SECRET_SUFFIXES)
    )


def _fail(msg: str, code: int = 2) -> None:
    print(f"ERROR: {msg}", file=sys.stderr)
    raise SystemExit(code)


# Owner, 2026-11-11. A bare version goes to `dev`, so releasing is always a
# choice someone typed. `main` is the release channel: Workpeg reviews each
# main version, and installs or publishes it only once it is approved. No
# other branch is ever reviewed, installed or run on Workpeg.
DEFAULT_BRANCH = "dev"
RELEASE_BRANCH = "main"

REF_HELP = (
    "the version to upload, as <version> (goes to the 'dev' branch) or "
    "<branch>:<version>. 'main:<version>' is the release: Workpeg reviews "
    "each main version and installs or publishes it only once it is "
    "approved. Every other branch is for development only and is never "
    "reviewed, installed or run on Workpeg."
)
BRANCH_HELP = (
    "the branch to upload to when the ref is a bare version "
    f"(default: {DEFAULT_BRANCH}). Use --branch {RELEASE_BRANCH} or "
    f"{RELEASE_BRANCH}:<version> to submit a release for review."
)


def parse_ref(ref: str, branch: Optional[str] = None) -> Tuple[str, str]:
    """
    Parse "<version>" or "<branch>:<version>" into (branch, version).

    A bare version goes to ``branch``, or to ``dev`` when none is named. A
    colon ref names its own branch, and a ``branch`` that disagrees with it
    is refused rather than one silently winning.
    """
    if branch is not None:
        branch = branch.strip()
        if not branch:
            _fail("--branch is empty")

    ref = ref.strip()
    if ":" in ref:
        branch_name, version = ref.split(":", 1)
        branch_name = branch_name.strip()
        if not branch_name:
            _fail("branch name before ':' is empty "
                  "(example: main:1.0.0, or just 1.0.0 for dev)")
        if branch is not None and branch != branch_name:
            _fail(f"'{ref}' names branch '{branch_name}' but --branch says "
                  f"'{branch}'. Give one: '{branch}:{version.strip()}', or "
                  f"'{ref}' without --branch.")
    else:
        # `submit main` would upload a version named "main" to dev, the
        # opposite of what was meant, so a bare branch name is refused.
        bare = ref.lower()
        if bare in (RELEASE_BRANCH, DEFAULT_BRANCH):
            _fail(f"'{ref}' is a branch, not a version: "
                  f"give {bare}:<version>")
        branch_name = branch if branch is not None else DEFAULT_BRANCH
        version = ref
    version = version.strip()

    if not version:
        _fail("version is empty "
              "(example: 1.0.0 for dev, main:1.0.0 for a release)")

    return branch_name, version


def submitted_line(branch: str, version: str) -> str:
    """The one line printed after a successful upload: what happens next."""
    ref = f"{branch}:{version}"
    if branch == RELEASE_BRANCH:
        return (f"{ref} is submitted for review. Workpeg installs or "
                "publishes it only once it is approved.")
    return (f"{ref} is uploaded for development only; not reviewed, "
            "installed or run on Workpeg; submit "
            f"{RELEASE_BRANCH}:{version} when it is ready.")


def project_releases_line(version: str) -> str:
    """Said when the registry closes ``function submit main:`` because the
    peg is released as a whole project (``workpeg project submit``)."""
    return (f"{RELEASE_BRANCH}:{version} was not uploaded: this peg is "
            f"released with `workpeg project submit {RELEASE_BRANCH}:"
            f"{version}`, which sends its whole source to be built and "
            "reviewed as one version, so the registry has closed `function "
            f"submit {RELEASE_BRANCH}:` for it. `function submit` still takes "
            f"its other branches: `workpeg function submit {version}` goes "
            f"to {DEFAULT_BRANCH}.")


def decode_jwt_payload_no_verify(token: str) -> dict:
    """
    Extract JWT payload WITHOUT verifying signature.
    We only use it to find peg_namespace for routing.
    Server will validate the token signature anyway.
    """
    parts = token.split(".")
    if len(parts) != 3:
        _fail("Invalid JWT format (expected 3 segments)")

    payload_b64 = parts[1]
    # Add required padding for base64url
    padding = "=" * (-len(payload_b64) % 4)
    payload_b64 += padding

    try:
        raw = base64.urlsafe_b64decode(payload_b64.encode("utf-8"))
        payload = json.loads(raw.decode("utf-8"))
        return payload
    except Exception:
        _fail("Could not decode JWT payload")


def build_tar_gz_bytes(source_dir: Path) -> bytes:
    """
    Create a tar.gz archive in memory from a source directory.
    Excludes common junk by default.
    """
    if not source_dir.exists():
        _fail(f"Project path not found: {source_dir}")

    if not source_dir.is_dir():
        _fail(f"Expected a project directory, got a file: {source_dir}")

    from workpeg.build import validate_function_project

    from workpeg.function_check import BundleRefused, check_bundle

    try:
        validate_function_project(source_dir)
    except (FileNotFoundError, NotADirectoryError) as e:
        _fail(str(e))

    # What Workpeg's install would refuse is refused here, before anything
    # is uploaded, with the install's own message. Before this check a refused
    # bundle uploaded cleanly and only an operator saw why it never ran.
    try:
        check_bundle(source_dir)
    except BundleRefused as e:
        _fail(f"{e} Workpeg would refuse to build this function, so it "
              "was not uploaded.")

    exclude_names = ALWAYS_EXCLUDED | {"dist", "build"}

    skipped_secrets: list[str] = []
    buf = io.BytesIO()
    with tarfile.open(fileobj=buf, mode="w:gz") as tar:
        for p in source_dir.rglob("*"):
            rel = p.relative_to(source_dir)

            if any(part in exclude_names for part in rel.parts):
                continue

            # Never bundle secrets, and never follow symlinks out of the project
            # (a link could point at anything on the machine). Belt-and-braces on
            # top of validate_function_project.
            if p.is_symlink():
                skipped_secrets.append(rel.as_posix() + " (symlink)")
                continue
            if _looks_secret(rel.name):
                skipped_secrets.append(rel.as_posix())
                continue

            if not p.exists():
                continue

            arcname = rel.as_posix()
            tar.add(p.as_posix(), arcname=arcname, recursive=False)

    if skipped_secrets:
        print(
            "  Skipped (looks like a secret / symlink, not bundled): "
            + ", ".join(sorted(skipped_secrets))
        )
    return buf.getvalue()


def submit_bundle(
    *,
    api_base: str,
    peg_id: str,
    token: str,
    branch_id: str,
    version: str,
    bundle_bytes: bytes,
    timeout_s: int = 60,
) -> dict:
    url = f"{api_base.rstrip('/')}/api/pegs/{peg_id}/functions/"

    files = {
        "bundle": ("bundle.tar.gz", bundle_bytes, "application/gzip"),
    }
    data = {
        "branch_id": branch_id,
        "version": version,
    }
    headers = {
        "Authorization": f"Bearer {token}",
    }

    r = requests.post(url, data=data, files=files,
                      headers=headers, timeout=timeout_s)
    if r.status_code >= 400:
        # try to show API error
        try:
            body = r.json()
        except Exception:
            body = r.text
        # A peg with a main peg version takes its releases as one unit, so
        # the registry refuses a main function on its own (design section
        # 2). Say what to run instead of the bare 409.
        if (r.status_code == 409 and branch_id == RELEASE_BRANCH
                and isinstance(body, dict)
                and "project submit" in str(body.get("detail", ""))):
            _fail(project_releases_line(version), code=1)
        _fail(f"Submit failed ({r.status_code}): {body}", code=1)

    return r.json()


def main(argv=None) -> None:
    parser = argparse.ArgumentParser(
        prog="workpeg submit",
        description="Upload a Workpeg function bundle to a Peg's registry.")
    parser.add_argument(
        "ref", metavar="ref", help=REF_HELP)
    parser.add_argument("--branch", default=None, help=BRANCH_HELP)
    parser.add_argument("--api", default=os.environ.get(API_ENV,
                        DEFAULT_API_BASE), help="API base URL")
    parser.add_argument("--path", default=os.environ.get(PATH_ENV,
                        "."), help="Function project directory")
    parser.add_argument("--timeout", type=int, default=60,
                        help="Request timeout (seconds)")
    args = parser.parse_args(argv)

    branch_name, version = parse_ref(args.ref, branch=args.branch)

    token = os.environ.get(JWT_ENV)
    if not token:
        _fail(f"Missing env var {JWT_ENV}")

    payload = decode_jwt_payload_no_verify(token)
    peg_id = payload.get("peg_namespace")
    if not peg_id:
        _fail(
            "JWT missing peg_namespace "
            "(cannot route to /api/pegs/{peg_id}/...)")

    source_dir = Path(args.path).resolve()
    bundle_bytes = build_tar_gz_bytes(source_dir)

    result = submit_bundle(
        api_base=args.api,
        peg_id=str(peg_id),
        token=token,
        branch_id=branch_name,
        version=version,
        bundle_bytes=bundle_bytes,
        timeout_s=args.timeout,
    )

    print(json.dumps(result, indent=2))
    # stderr, so stdout stays the registry's JSON for anything piping it.
    print(submitted_line(branch_name, version), file=sys.stderr)


if __name__ == "__main__":
    main()
